(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fy"] = {"ui":{"skip":"Gean nei de ynhâld","back":"← Werom nei AI-gile","lang.button":"Taal: {name}","lang.dialog":"Kies in taal","lang.search":"Taal sykje","lang.none":"Gjin taal fûn","lang.notYet":"{name} is noch net oersetten","theme.aria":"Wikselje tusken ljocht en tsjuster tema","theme.toLight":"Wikselje nei ljocht tema","theme.toDark":"Wikselje nei tsjuster tema","words.underline":"Dizze wurden op 'e side ûnderstreekje","words.underlineHelp":"Hâld de mûs boppe in stippele wurd of tik derop om te sjen wat it betsjut.","index.title":"AI-gile: dyn AI-ûntwikkelteam, op ien boerd","index.description":"AI-gile is in kanbanboerd foar AI-koadeteams. Se wurkje wylst do sliepst; do krijst ien koarte steapel mei dingen om te beslissen, te testen en te akseptearjen.","hero.logoAlt":"AI-gile-boerdikoan","hero.h1.html":"Dyn AI-ûntwikkelteam, op ien&nbsp;boerd.","hero.alpha":"🐣 Sletten pre-alfa","hero.alphaTitle":"Betiid en net ôf: tank dat do it besiket!","hero.lede":"Se bouwe wylst do sliepst. Do wurdst wekker mei ien koarte steapel: in pear fragen, in pear dingen om te testen, in pear pearse diamanten. Klik, akseptearre, werom nei dyn kofje.","dl.windows":"Windows-app","dl.browser":"Brûk it yn dyn browser","dl.soon":"Komt gau","dl.notify":"🔔 Lit my witte as it iepengiet","dl.notifySmall":"Alfa of beta","hero.secondary":"Agile, mar it team hat nea in stânkofje nedich. (Se hâlde de stânddei-oerlis dochs.)","pitch.h2":"AI-gile yn safolle wurden as do wolst","pitch.lede":"Kies in lingte, fan ien wurd oant 144. Elke lingte is in eigen beskriuwing, skreaun foar dy maat. Sleep de skowler of brûk de pylktoetsen.","pitch.rangeLabel":"Lingte yn wurden","pitch.dice":"🎲 in oare ferzje","pitch.words.one":"{n} wurd","pitch.words.other":"{n} wurden","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} teken","pitch.chars.other":"{n} tekens","count.line.html.one":"{n} kaart op it boerd op dit stuit","count.line.html.other":"{n} kaarten op it boerd op dit stuit","features.aria":"Wat it docht","f.pile.h":"Ien steapel foar dy","f.pile.html":"<b>Foar dy</b> hat alles wat op dy wachtet, oer alle projekten hinne: fragen, dingen om te testen, taken dy't allinnich in minske dwaan kin. Dyn wachtrige seit wat folget en hoe lang it duorret.","f.sleep.h":"Teams dy't wurkje wylst do sliepst","f.sleep.p":"Elk projekt hat in lieder en in team fan AI-aginten. Kommentearje op in kaart en it team wurdt wekker, docht it wurk en jout it werom mei stappen dy't ek in wurch minske folgje kin.","f.tester.h":"In AI-tester kontrolearret earst","f.tester.p":"Foardat der wat by dy komt, folget in tester de stappen yn in kopy fan de app en lit sjen wat er seach, mei in skermôfbylding. Blêdzje troch de slagge kaarten en akseptearje mei ien klik.","f.proof.h":"Bewiis, gjin beloften","f.proof.p":"Elke oerdracht lit sjen wat feroare is: de bestannen, de diff, de skermôfbyldingen. Net elke app iepenmeitsje om te sjen oft it klear is.","f.chat.h":"Praat mei dyn lieders","f.chat.p":"In Discord-eftige balke: ien ikoan per projekt, pearse diamanten foar wat dy nedich hat. Stjoer in lieder in idee; hy makket der kaarten en in plan fan, mei in ✅ Go-knop.","f.tidy.h":"Hâldt himsels oarderlik","f.tidy.p":"Besibbe kaarten smelte ta ien, wazige titels wurde rjochte, en in tokenkontrôle hâldt de koade licht. Minder om tusken te wikseljen, minder om oan te tinken.","f.private.h":"Fan dy, op dyn kompjûter","f.private.li1":"It boerd rint op dyn eigen masine en antwurdet allinnich dy.","f.private.li2":"Priveeberjochten tusken minsken binne end-to-end fersifere.","f.private.li3":"Gjin akkounts, gjin trackers, gjin cookies.","f.lang.h":"Yn dyn taal","f.lang.p":"Mear as 120 talen, fan Nederlânsk, Welsk en Japansk oant piraat, Yoda en Klingon, mei in flugge wiksel werom nei Ingelsk foar de ûntwikkelderswurden.","tl.aria":"Tiidline fan it earste petear oant de roadmap","tl.h2":"Fan it earste petear oant wat folget","tl.lede":"Echte datums en tiden, yn dyn eigen tiidsône. Nei hjoed is it it plan, sûnder tasein datums.","tl.today":"Hjoed","tl.planned":"pland","tl.cards.one":"{n} kaart","tl.cards.other":"{n} kaarten","join.h2":"Doch mei","join.lede":"AI-gile wurdt boud troch in lyts minske en in grut tal geduldige aginten. It is foarearst privee, in sletten alfa mei freonen. Wolst it besykje as it iepengiet?","join.btn":"Meld dyn belangstelling","join.small":"Wy mailje dy, mear net","footer.tag":"AI-gile. Gjin trackers, gjin cookies, gjin stânkofje.","footer.licence":"Bedriuwslisinsje","footer.status":"Status","footer.privacy":"Wat wy bewarje","form.sending":"Ferstjoere…","form.failed":"Dat slagge net: besykje it letter wer.","form.offline":"Koe AI-gile net berikke: besykje it letter wer.","form.keep":"Wy brûke dit allinnich om dy te antwurdzjen, dêrnei wiskje wy it. Gjin trackers, gjin cookies.","form.keepLink":"Wat wy bewarje","interest.title":"AI-gile: lit my witte as de alfa iepengiet","interest.description":"Lit dyn e-mailadres efter om te hearren wannear't de sletten alfa of beta fan AI-gile iepengiet.","interest.h1":"🔔 Lit my witte as it iepengiet","interest.lede":"AI-gile sit yn sletten pre-alfa. Lit dyn e-mailadres efter en wy skriuwe ien kear, as der in plak foar dy is.","interest.email":"Dyn e-mailadres","interest.which":"Hokker test?","interest.alpha":"Sletten alfa: betiid, rûch, in soad feroarings","interest.beta":"Beta: stabiler, letter","interest.both":"Beide, wat earst komt","interest.submit":"Set my op de list","interest.thanks":"Tank! Do stiest op de list.","licence.title":"AI-gile: bedriuwslisinsje","licence.description":"AI-gile brûke yn dyn bedriuw? Freegje in fergese bedriuwslisinsje oan.","licence.h1":"📜 Bedriuwslisinsje","licence.lede":"AI-gile brûke op it wurk? Fertel ús wa't do bist en wat do dochst. As it wat goeds docht, is de lisinsje fergees.","licence.company":"Bedriuw","licence.website":"Webside","licence.what":"Wat do dochst","licence.how":"Hoe't it de wrâld helpt","licence.email":"E-mail","licence.submit":"Oanfreegje","licence.thanks":"Tank! Wy antwurdzje per e-mail.","status.title":"AI-gile-status","status.h1":"AI-gile-status","status.quiet":"Alles stil","status.intro":"Wurket AI-gile no? Dizze side kontrolearret elke 5 minuten de webside, it dielen fan boerden, oproppen en de download.","status.up":"Wurket (antwurde yn {ms} ms)","status.slow":"Antwurde net by de lêste kontrôle, besiket it wer","status.down":"Plat: antwurde net by de lêste twa kontrôles","status.svc.web":"Webside","status.svc.web.offers":"Dizze side: wat AI-gile is, en it belangstellingsformulier","status.svc.boards":"Boerden diele","status.svc.boards.offers":"Iepenbiere boerden, berjochten tusken freonen en útnoegings","status.svc.calls":"Oproppen","status.svc.calls.offers":"Lûd, fideo en skerm diele yn AI-gile","status.svc.download":"Download","status.svc.download.offers":"De Windows-ynstallaasje en útnoegingskeppelings","status.checking":"Kontrolearje…","status.offline":"Kin de statustsjinst no net berikke (besykje it wer)","status.updated":"bywurke {ago}","status.justNow":"krekt no","status.min":"{n} min lyn","status.hours":"{n} oere lyn","status.days":"{n} d lyn","privacy.title":"AI-gile: wat wy bewarje","privacy.h1":"Wat wy bewarje","privacy.lede":"Koartsein: allinnich wat do ús stjoerst, en net lang.","privacy.only":"Allinnich wat do ús stjoerst: wat do yn in formulier typst, lykas dyn e-mailadres. Fierder neat oer dy.","privacy.sealed":"It wurdt fersegele, sadat ús server it net lêze kin: yn dyn browser, foardat it fuortgiet (by in âldere browser, op it momint dat it oankomt). Allinnich ús eigen boerd kin it iepenje.","privacy.server":"It wurdt fan 'e server wiske sa gau as it ús boerd berikt. Wat der nei 30 dagen noch stiet, wurdt dochs wiske.","privacy.board":"Wy bewarje it op ús boerd allinnich oant wy dy antwurde ha, dêrnei wiskje wy it dêr ek.","privacy.none":"Gjin trackers, gjin cookies, gjin analytics.","privacy.local":"Dyn taal en dyn kar foar ljocht of tsjuster bliuwe yn dyn eigen browser. Se wurde nea nei ús stjoerd.","privacy.ask":"Wolsto dat it earder fuort is? Antwurdzje op ús e-mail en sis it mar.","live.h2":"Sjoch it boud wurde, live","live.caption":"Elke kaart is ferburgen: do sjochst de foarm fan it wurk, net de wurden.","live.watching.one":"live: {n} sjocht","live.watching.other":"live: {n} sjogge","live.last.now":"Lêste kaart krekt ferpleatst","live.last.min.one":"Lêste kaart {n} min lyn ferpleatst","live.last.min.other":"Lêste kaart {n} min lyn ferpleatst","live.last.hour.one":"Lêste kaart {n} oere lyn ferpleatst","live.last.hour.other":"Lêste kaart {n} oeren lyn ferpleatst","live.last.day.one":"Lêste kaart {n} dei lyn ferpleatst","live.last.day.other":"Lêste kaart {n} dagen lyn ferpleatst","live.offline":"It live-boerd nimt efkes in azem. Sjoch gau wer.","live.cols":"Backlog|Te dwaan|Dwaande|Team kontrolearret|Foar dy om te test|Foar it team|Klear"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegearre."]},{"n":2,"texts":["Robots wurkje.","Aginten, oarderlik.","Ideeën, boud."]},{"n":3,"texts":["Kanban foar robots.","Ideeën wurde funksjes.","Fergees agintkanban."]},{"n":5,"texts":["Kanbanboerd rinne troch aginten.","Do skriuwst, aginten bouwe.","Fergees, lokaal, getest, in bytsje gek."]},{"n":8,"texts":["In fergees kanbanboerd dêr't AI-aginten wurkje.","Skriuw in idee. Aginten bouwe it. Do aksepteart.","Agile foar ien minske en in soad geduldige robots."]},{"n":13,"texts":["In kanbanboerd op dyn kompjûter dêr't AI-aginten de kaarten oppakke en útfiere.","Skriuw in idee. In team fan aginten bout it. In tester kontrolearret it.","Fergees, gjin akkounts, gjin trackers: in boerd, in pear robots, en do as baas."]},{"n":21,"texts":["AI-gile is in kanbanboerd om mei AI-koadeaginten te wurkjen. Se pakke de kaarten op; do test se en aksepteart se.","Elk projekt krijt in lieder en in team fan AI-aginten. Kommentearje op hokker kaart ek en it team giet oan it wurk.","In fergees, persoanlik taakboerd dat op dyn eigen kompjûter rint. De wurkers binne robots. Dejinge dy't ja seit, bist do."]},{"n":34,"texts":["Do set ideeën op in boerd. In team fan AI-aginten makket der wurkjende funksjes fan, test se en jout se werom mei stappen om út te probearjen. Neat telt as klear oant do it seist.","AI-gile is in selsmakke kanbanboerd dat Rich boude mei in soad help fan de aginten dy't it no beheart. It is fergees, rint op dyn kompjûter en wurdt mei freonen dield, net ferkocht.","Stel dy in gewoan kanbanboerd foar, mei kolommen fan Backlog oant Klear, útsein dat de kaarten oppakt wurde troch AI-aginten. Se melde foarútgong, stelle fragen as se fêst sitte, en wachtsje altyd op dyn tommen omheech."]},{"n":55,"texts":["AI-gile is in kanbanboerd wêrfan it team út AI-aginten bestiet. Elk projekt hat in lieder dy't it wurk plant en helpers dy't it bouwe. As in funksje klear is, besiket in AI-tester it út en makket in skermôfbylding, dan komt it op dyn steapel telâne. Akseptearje it, of kommentearje en se wurkje it nei.","It begûn as ien minske syn manier om in soad AI-koadesesjes tagelyk by te hâlden, en groeide út ta in echt boerd. It rint op dyn masine, hat gjin akkount nedich en hat gjin trackers. It is fergees foar freonen en nijsgjirrigen. It is ek net ôf, dus rekkenje op rûge rânen en no en dan in ferrassing.","Dit is de earlike ferzje. Do moatst noch altyd de ideeën hawwe, en do moatst de resultaten noch altyd kontrolearje. Wat AI-gile docht is alles dêrtusken: it hâldt de kaarten op oarder, wekket de krekte agint as do kommentearrest, lit presys sjen wat feroare is, en set it alles op ien koarte steapel foar dy."]},{"n":89,"texts":["AI-gile is in fergees kanbanboerd dat do op dyn eigen kompjûter rinne litst. Yn plak fan minsken hat elk projekt in team fan AI-aginten: in lieder dy't dyn ideeën omsette yn kaarten en in plan, en helpers dy't de kaarten yn folchoarder fan wichtichheid oppakke. As der wat boud is, folget in AI-tester de teststappen en lit dy sjen wat er seach. Dan wachtet it op ien steapel mei de namme Foar dy. Do aksepteart it, of do kommentearrest en it team besiket it noch ris. Neat komt ea by Klear sûnder dy.","Inkelde funksjes dy't do miskien net ferwachtest. In nachtwacht hâldt de kolom Te dwaan fol wylst do sliepst, mei kaarten dêr't gjin antwurd fan dy foar nedich is. In tokenteller lit sjen hoefolle de aginten hjoed en dizze wike brûkt hawwe, en de Gjin-token-modus seit harren dat se ophâlde moatte mei útjaan. Do kinst freonen berjochten stjoere, en priveeberjochten binne end-to-end fersifere. It boerd praat sa'n 120 talen, ûnder oaren Nederlânsk, Flaamsk, piraat en Klingon. Neat dêrfan kostet in sint, en gjinien besiket it dy oan te smeren.","AI-gile is in lyts, persoanlik projekt, gjin bedriuw. Rich woe foar ferskate AI-koadeprojekten soargje sûnder elke app iepen te dwaan om te sjen hoe't it derfoar stie, dus hy en de aginten boude dêr in boerd foar, en brûkten it boerd doe om de rest sels te bouwen. It sit yn sletten pre-alfa, wat betsjut dat it wurket, foar it grutste part, foar in hânfol freonen. Der is gjin prizenside, gjin nijsbrief en gjin groeiplan. As it nuttich klinkt, kinst freegje om it út te probearjen as it wat fierder iepengiet."]},{"n":144,"texts":["AI-gile is in kanbanboerd foar ien minske en in soad AI-aginten. It rint op dyn eigen kompjûter en is folslein fergees. Do foegest projekten ta, en elk projekt krijt in lieder en in lyts team. Do praatst mei de lieder, in bytsje as op Discord, en beskriuwst in idee; de lieder makket der kaarten en in plan fan, en wachtet dan oant do op Go drukst. It team wurket de kaarten ôf op folchoarder fan wichtichheid, mei in ienfâldige kommandorigel makke foar taalmodellen. Foardat der wat by dy weromkomt, folget in AI-tester de stappen yn in kopy fan de app en foeget in skermôfbylding ta. Klear wurk komt op dyn steapel mei de feroare bestannen en de diff. Do aksepteart it, of do litst in kommentaar efter en it team wurdt wekker en besiket it opnij. Allinnich do kinst in kaart nei Klear ferpleatse.","In dei mei AI-gile, rûchwei. Jûns litst in pear kommentaren efter: dizze knop stiet op it ferkearde plak, dy list moat sortearre wurde, koe der ek in tsjuster tema komme. Do giest op bêd. De aginten lêze de kommentaren, meitsje de feroarings, testen se en jouwe se werom. As Te dwaan leech rekket, folt de nachtwacht it út de backlog oan mei kaarten dêr't gjin antwurd fan dy foar nedich is. Moarns leit der ien koarte steapel: in pear fragen en in pear dingen om út te probearjen, elk mei stappen dy't in sliepeachtich minske folgje kin en in skermôfbylding fan it wurkjen. Do klikst der troch, aksepteart de goede en stjoerst de rest werom. In tokenteller lit sjen wat it allegear brûkt hat, en de Gjin-token-modus is der foar de mager wiken. Dan ytst dyn moarnsiten, dêr't de aginten noch net mei helpe kinne.","Earst, wat AI-gile net is. It is gjin startup, it is net te keap, en gjinien sammelet dyn gegevens. It is in fergees boerd dat op dyn kompjûter rint, sûnder akkounts, sûnder trackers en sûnder cookies. Wat it wol is: ien oarderlike plak om alle AI-koadeprojekten tagelyk te sjen, mei in team fan aginten dat de kaarten docht en do dy de besluten nimst. It smelt besibbe kaarten gear, makket wazige titels goed, en hâldt yn de gaten hoe licht de koade bliuwt. It praat sa'n 120 talen, fan Nederlânsk en Flaamsk oant piraat en Klingon. Freonen kinne inoar berjochten stjoere, privee en fersifere. It is boud troch Rich en in grut tal geduldige aginten, meast troch himsels te brûken. It sit yn sletten pre-alfa, dus it is op plakken noch rûch. As it dy leuk klinkt, freegje it freonlik en miskien komst der betiid yn."]}],"quips":{"1":"Ien wurd. Dryst. Miskien te dryst.","3":"Trije wurden. Al earliker as de measte produktsiden.","8":"Acht wurden. Noch koarter as in stânddei-oerlis.","21":"De lingten binne trouwens story points. Fansels binne se dat.","55":"Fiifenfyftich wurden. Twa kaarten binne klear wylst do dit lies.","144":"Dat is de lange. Der is gjin 233. De aginten binne op bêd."}},"timeline":{"first-idea.name":"It earste idee","first-idea.line":"It allereerste petear, foardat der ien rigel koade wie.","first-board.name":"Earste boerd","first-board.line":"In boerd dat syn eigen bou byhâldt: kaarten, kolommen, slepe en delsette, projekten.","team-roles.name":"Team en rollen","team-roles.line":"Agintprofilen, teamsjablonen, romtes en wa't wat docht.","install.name":"Ynstallaasje en útjeften","install.line":"In zip dy't in freon ynstallearje kin, selsbywurkjen, kanalen en weromdraaie.","usage-saver.name":"Gebrûksbesparring","usage-saver.line":"Mjit wat runs kostje, hâld de koade licht, bewarje dyn limyt.","friends.name":"Freonen en dielen","friends.line":"Priveeberjochten, in forskoft relay, útnoegingen, rollen en dielde projekten.","languages.name":"Talen","languages.line":"Elke skermtekst yn in taalbestân, mei Nederlânsk en Flaamsk earst.","ai-tester.name":"AI-tester","ai-tester.line":"In tester kontrolearret elke oerdracht earst en lit sjen wat er seach.","website.name":"De webside","website.line":"aigile.lol, de teaser en dizze tiidline.","streaming.name":"Chat en streamen","streaming.line":"Discord, Twitch, OBS, streamermodus, GIF's en emoji's.","no-ai.name":"Edysje sûnder AI","no-ai.line":"In boerd foar minsken dy't koadzje sûnder AI, en iepenbiere boerden.","night-watch.name":"Nachtwacht","night-watch.line":"In wachter en Scrum Master hâlde de teams op taak wylst do sliepst.","p-more.name":"Al it oare","p-more.line":"Lytsere ideeën dy't noch op har bar wachtsje.","p-android.name":"Tillefoan en Android","p-android.line":"Berik dyn boerd fan in tillefoan, dêrnei in eigen Android-app.","p-release.name":"Alfa en fierder","p-release.line":"Sletten alfa, de libbene side, dêrnei beta.","p-languages.name":"Mear talen","p-languages.line":"Mear as hûndert talen, en in ûnderdompelmodus foar learlingen.","p-engines.name":"Mear AI-motoren","p-engines.line":"Kies Claude, Codex of Gemini per agint.","p-pro.name":"Profesjonele praktyk","p-pro.line":"Risikolabels, gearfoegingspoarten, ynsidintkaarten en leuningen.","p-self.name":"Soargje foar dy","p-self.line":"Wurch-modus, selssoarch-herinneringen en 4:20.","p-servers.name":"Servers en skaal","p-servers.line":"Globale serverynstellings, rollen en planne foar groei.","p-livestream.name":"Streamingekstra's","p-livestream.line":"Twitch-chat, eigen emoji's en in iepenbier live byld."},"words":{"button":"📖 Ûntwikkelderswurden","h":"📖 Ûntwikkelderswurden útlein","intro":"De wurden dy't ûntwikkelders (en de AI-teams) brûke, yn gewoan Frysk.","search":"In wurd sykje…","none":"Gjin wurd dat hjirby past.","close":"Slute","list":[{"id":"backlog","word":"Backlog","text":"Ideeën en wurk dat noch net pland is. Dêr wurdt neat oan wurke oant it nei Te dwaan giet."},{"id":"sprint","word":"Sprint","text":"In koart stik wurk (faak in wike of twa) mei in ôfpraat set kaarten dy't klear moatte.","also":["sprints"]},{"id":"standup","word":"Stand-up","text":"In flugge ynchecking: wat elk teamlid die, wat er folgjende docht, en wat him tsjinhâldt.","also":["standup","stand-ups"]},{"id":"bug","word":"Bug","text":"Wat net wurket sa't it moat.","also":["bugs"]},{"id":"test","word":"Test","text":"In klear stik wurk besykje om te kontrolearjen dat it docht wat frege is, foardat do it akseptearrest.","also":["tests"],"noTip":1},{"id":"commit","word":"Commit","text":"In bewarre momintopname fan de koade, mei in koart notysje fan wat feroare is. Do kinst altyd werom nei ien.","also":["commits"]},{"id":"push","word":"Push","text":"Bewarre momintopnames (commits) fan dizze kompjûter nei GitHub stjoere, sadat se bewarre en dield binne."},{"id":"branch","word":"Branch","text":"In aparte line fan wurk yn de koade, sadat wizigingen makke wurde kinne sûnder de haadferzje oan te rekken.","also":["branches"]},{"id":"merge","word":"Merge","text":"De wizigingen fan in branch wer yn de haadferzje gearfoegje."},{"id":"repo","word":"Repo","text":"De map fan it projekt mei koade en de folsleine skiednis fan commits, meast ek op GitHub bewarre.","also":["repository"]},{"id":"refactor","word":"Refactor","text":"De koade opromje sûnder te feroarjen wat er docht: lytsere bestannen, dúdlikere nammen, minder werhelling."},{"id":"deploy","word":"Deploy","text":"In nije ferzje live sette, bygelyks op in server dêr't minsken it brûke."},{"id":"kanban","word":"Kanban","text":"In boerd mei kolommen (Te dwaan, Dwaande, Klear) dêr't kaarten fan links nei rjochts gean as it wurk foarútgiet."},{"id":"wip","word":"WIP-limyt","text":"Work in progress: it maksimum oantal kaarten yn in kolom, sadat it team dingen ôfmakket foardat er mear begjint.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Freegje om de wizigingen fan in branch te kontrolearjen en yn de haadferzje gear te foegjen.","also":["PR"]},{"id":"hook","word":"Hook","text":"In lyts kommando dat op in bepaald momint fansels rint, bygelyks as in AI-sesje begjint, sadat it team dyn reaksjes heart.","also":["hooks"]},{"id":"token","word":"Token","text":"De ienheid dêr't AI-gebrûk yn teld wurdt: sawat in pear letters tekst lêzen of skreaun. Minder tokens, mear oer fan dyn abonnemint.","also":["tokens"]},{"id":"agent","word":"Agint","text":"In AI dy't sels oan in taak wurket: lêst de koade, makket wizigingen, docht kontrôles en makket ferslach.","also":["aginten"]}]}};
